        responses: &mut Vec<DT::Response>,
        num_ops_per_thread: &mut Vec<usize>,
        thread_ops_data: Tracked<ThreadOpsData<DT>>,
    ) -> (res: Tracked<ThreadOpsData<DT>>)
        requires
            self.wf(),
            thread_ops_data@.distribute_thread_resps_pre(
