                thread_ops_data@.request_ids@.len(),
            ),
        ensures
            res@.distribute_thread_resps_post(self.flat_combiner_instance),
    {
        let tracked ThreadOpsData {
            flat_combiner: flat_combiner,
            request_ids: request_ids,
            local_updates: local_updates,
